"""Comprobación de una línea ya traducida cuyo sitio cambió de forma dudosa: ¿es otro texto, o
solo una molestia (un adorno que parpadea, un brillo, partículas, el texto resaltado de otro
color)? Se decide con lo que lee el lector en la imagen de antes y en la mediana de los
fotogramas de ahora, más rasgos de la imagen, con un modelo pequeño (árboles de decisión
potenciados) entrenado con el banco de pruebas (banco.py) y el lector real de Windows.

Este archivo lo rellena en parte la herramienta de ajuste: MODELOS es su salida.
"""
import difflib
import math
import re
import unicodedata

NOMBRES_IMAGEN = ("dif", "en", "n", "frac", "pos", "d2")


def _norm(t):
    import envivo
    return "".join(envivo._palabras(t))


def _cifras(t):
    return re.sub(r"\D", "", unicodedata.normalize("NFKC", t or ""))


def rasgos(leido_antes, leido_ahora, img_primero, img_ahora, cjk):
    """Vector de rasgos. img_*: dict con NOMBRES_IMAGEN (banco.rasgos_imagen sin prefijo)."""
    a, b = _norm(leido_antes), _norm(leido_ahora)
    if not a and not b:
        sim = 1.0
    elif not a or not b:
        sim = 0.0
    else:
        sim = difflib.SequenceMatcher(None, a, b).ratio()
    comun = 0
    while comun < min(len(a), len(b)) and a[comun] == b[comun]:
        comun += 1
    pa, pb = _palabras(leido_antes), _palabras(leido_ahora)
    corto, largo = (pa, pb) if len(pa) <= len(pb) else (pb, pa)
    out = [sim, float(_cifras(leido_antes) != _cifras(leido_ahora)), float(not b), float(not a),
           len(b) / max(1, len(a)),
           comun / max(1, len(a), len(b)),                                    # cuánto coincide desde el principio
           float(max(len(a), len(b)) - comun <= 3),                            # solo cambia el final
           float(bool(corto) and largo[:len(corto)] == corto and len(largo) - len(corto) <= 1)]  # falta/sobra la última palabra
    out += [float(img_primero[k]) for k in NOMBRES_IMAGEN]
    out += [float(img_ahora[k]) for k in NOMBRES_IMAGEN]
    out.append(float(cjk))
    return out


def predecir(modelo, x):
    """Probabilidad de que sea OTRO texto, con un modelo exportado por la herramienta de ajuste."""
    z = modelo["inicio"]
    for arbol in modelo["arboles"]:
        n = 0
        while arbol["izq"][n] >= 0:
            n = arbol["izq"][n] if x[arbol["rasgo"][n]] <= arbol["umbral"][n] else arbol["der"][n]
        z += modelo["paso"] * arbol["valor"][n]
    return 1.0 / (1.0 + math.exp(-z))


def _palabras(t):
    import envivo
    return envivo._palabras(t)


_CURSOR = set("l|i1!]")


def misma_lectura(antes, ahora):
    """El lector lee exactamente lo mismo (letras y números): aunque la imagen cambiara, la
    traducción sería la misma, así que no hay nada que quitar (una flecha o un cursor que
    parpadean, un brillo...)."""
    a, b = _norm(antes), _norm(ahora)
    if not a or _cifras(antes).rstrip("1") != _cifras(ahora).rstrip("1"):
        return False
    if a == b:
        return True
    # un cursor que parpadea al final se lee como una letra suelta (l, |, i, 1)
    corto, largo = (a, b) if len(a) < len(b) else (b, a)
    return len(largo) - len(corto) == 1 and largo.startswith(corto) and largo[-1] in _CURSOR


